Lemma ag_len_grp_cap : forall sc req c2 n3,
  1 <= size_class sc <= 8191 -> 0 <= req -> req + 4 <= 16 * size_class sc ->
  1 <= c2 <= 32 -> 16 * size_class sc * c2 < 2^20 ->
  (n3 = page_round_up_Z (16 * size_class sc * c2 + 16) \/ n3 = page_round_up_Z (req + 20)) ->
